 OR EXISTS(SELECT 1 FROM pg_catalog.pg_cast WHERE castsource IN (16,17,18,19,20,21,22,23,25,26,194,1000,1005,1007,1009,1016,1028,1033,1034,2277) AND casttarget IN (114,3802)) THEN
