-- Scan every covered column BEFORE any actual sender/row encoder dispatch.
IF EXISTS(SELECT 1 FROM pg_catalog.pg_attribute a JOIN pg_catalog.pg_class c ON c.oid=a.attrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE a.attnum>0 AND NOT a.attisdropped AND ((n.nspname='public' AND c.relname=ANY(native_membership_guard.coverage())) OR n.nspname='native_membership_guard') AND (a.atthasmissing IS DISTINCT FROM (a.attmissingval IS NOT NULL)
 OR (a.attmissingval IS NOT NULL AND NOT (
 (n.nspname='public' AND c.relname='spaces' AND a.attname='allow_guests' AND a.atttypid=16) OR
 (n.nspname='public' AND c.relname='community_owner_authority' AND a.attname='roster_source_revision' AND a.atttypid=20) OR
 (n.nspname='public' AND c.relname='space_lifecycle_aggregates' AND a.attname='evidence_compacted' AND a.atttypid=16))))) THEN
 RAISE EXCEPTION 'source type qualification failed' USING ERRCODE='55000'; END IF;
FOR r IN SELECT n.nspname,c.relname,a.attnum,a.attname,a.atttypid,a.attmissingval FROM pg_catalog.pg_attribute a JOIN pg_catalog.pg_class c ON c.oid=a.attrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE a.attnum>0 AND NOT a.attisdropped AND ((n.nspname='public' AND c.relname=ANY(native_membership_guard.coverage())) OR n.nspname='native_membership_guard') ORDER BY a.attrelid,a.attnum LOOP
 IF r.attmissingval IS NULL THEN CONTINUE; END IF;
 IF r.nspname='public' AND r.relname='spaces' AND r.attname='allow_guests' AND r.atttypid=16 THEN
  good:=pg_catalog.array_send(r.attmissingval)=pg_catalog.array_send(ARRAY[true]::pg_catalog.bool[]);
 ELSIF r.nspname='public' AND r.relname='community_owner_authority' AND r.attname='roster_source_revision' AND r.atttypid=20 THEN
  good:=pg_catalog.array_send(r.attmissingval)=pg_catalog.array_send(ARRAY[0]::pg_catalog.int8[]);
 ELSIF r.nspname='public' AND r.relname='space_lifecycle_aggregates' AND r.attname='evidence_compacted' AND r.atttypid=16 THEN
  good:=pg_catalog.array_send(r.attmissingval)=pg_catalog.array_send(ARRAY[false]::pg_catalog.bool[]);
 ELSE RAISE EXCEPTION 'source type qualification failed' USING ERRCODE='55000'; END IF;
 IF good IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'source type qualification failed' USING ERRCODE='55000'; END IF;
END LOOP;
